const ultima_mensagem_da_fila = $input.last()
const mensagem_do_workflow = $('Info').first()

if (ultima_mensagem_da_fila.json.id_mensagem !== mensagem_do_workflow.json.id_mensagem) {
  // Mensagem encavalada, para o workflow
  return [];
}

// Pass-through da fila de mensagens
return $input.all();

const items = $input.all()
const results = [];

for (const item of items) {
    const mensagem = (item.json.mensagem || item.json.mensagem_audio || '').replace(/\\n/g, '\n')                                            
      .toLowerCase()                                                    
      .trim();   

    // Define reaction based on message content
    let reaction = null;
    let clear_memory = false;

    // Detect greetings - clear memory for fresh session
    const isGreeting = /^(oi|olá|ola|bom dia|boa tarde|boa noite|hey|hello|e ai|eai|tudo bem|tudo bom|opa)(\s|\?|!|,|$)/i.test(mensagem);

    if (isGreeting) {
      reaction = '🤝';
      clear_memory = true;
    } else if (mensagem.match(/(obrigado|valeu|thanks|brigado)/i)) {
      reaction = '🫡';
    } else if (mensagem.match(/(consultar|verificar|buscar|checar)/i)) {
      reaction = '👀';
    }

    results.push({
      json: {
        ...item.json,
        auto_reaction: reaction,
        clear_memory: clear_memory
      }
    });
  }

return results;

let text = $('Secretária').first().json.output || '';

// Remove marcador interno
text = text.replace(/\[FORA_DE_ESCOPO\]\s*/g, '').trim();

const shortReplies = ['ok', 'blz', 'bl', 'beleza', 'vlw', 'flw', 'ta'];

if (!text || (text.trim().length < 5 && !shortReplies.includes(text.trim().toLowerCase()))) {
    return [{ json: { text: 'Desculpe, poderia repetir sua solicitação?' } }];
}

// ** para * (negrito WhatsApp)
text = text.replace(/\*\*/g, '*');

// Remove headers markdown
text = text.replace(/^#+\s*/gm, '');

// Substitui nome completo por primeiro nome nas saudações
text = text.replace(/^(Olá|Oi|E aí|Opa),?\s+([A-ZÁÉÍÓÚÀÂÊÔÃÕÇ][\wÀ-ÿ]+)(?:\s+[A-ZÁÉÍÓÚÀÂÊÔÃÕÇ][\wÀ-ÿ]+)+/m, '$1, $2');

// Quebra linha antes de intros de lista
text = text.replace(/\.\s+(Me manda|Manda|Segue|Nossos|Veja|Confira|Os serviços|Os horários)/g, '.\n\n$1');

// Quebra linha antes de bullet points
text = text.replace(/\s+([•\-\*]\s)/g, '\n$1');

// Quebra linha antes de frases de encerramento
text = text.replace(/\.\s+(Se quiser|Caso queira|Pode mandar|Qualquer dúvida|Estou às ordens|Estamos à disposição)/g, '.\n\n$1');

// Quebra linha antes de emoji SOMENTE se ele estiver no início de uma "palavra" após espaço
// (evita quebrar quando emoji está colado no fim de uma frase como "confirmado!✅")
text = text.replace(/(?<=\w)\s+([\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}])/gu, '\n$1');

// Quebra após ponto final (exceto abreviações)
text = text.replace(/(?<!Prof|Dr|Dra|Sr|Sra|R|Av|Tel|Cel|Pç|CEP)\.\s+(?=[A-ZÁÉÍÓÚÀÂÊÔÃÕÇ])/g, '.\n\n');

// Limpa 3+ quebras de linha
text = text.replace(/\n{3,}/g, '\n\n');

// Aviso de pontualidade em confirmações
if (text.includes('confirmado') && !text.includes('Tente chegar')) {
    text = text.trimEnd() + '\n\nTente chegar 10 minutos antes.';
}

return [{ json: { text } }];

